/**
 * Booking Card Component
 * Displays booking information in card format
 */

import React from 'react';
import { Link } from 'react-router-dom';
import './BookingCard.css';

const BookingCard = ({ booking, onCancel }) => {
  const eventDate = new Date(booking.eventId.date);
  const formattedDate = eventDate.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });

  const isUpcoming = eventDate > new Date();

  return (
    <div className="booking-card">
      <div className="booking-header">
        <h3>{booking.eventId.title}</h3>
        <span className={`status ${booking.status}`}>{booking.status}</span>
      </div>

      <div className="booking-details">
        <p><strong>Location:</strong> {booking.eventId.location}</p>
        <p><strong>Date:</strong> {formattedDate} at {booking.eventId.time}</p>
        <p><strong>Tickets:</strong> {booking.numberOfTickets}</p>
        <p><strong>Total Price:</strong> ₹{booking.totalPrice}</p>
      </div>

      <div className="ticket-numbers">
        <strong>Ticket Numbers:</strong>
        <div className="tickets-list">
          {booking.ticketNumbers?.map((ticket, idx) => (
            <span key={idx} className="ticket-badge">{ticket}</span>
          ))}
        </div>
      </div>

      <div className="booking-actions">
        <Link to={`/ticket/${booking._id}`} className="btn-primary">
          View Ticket
        </Link>
        {booking.status === 'confirmed' && isUpcoming && (
          <button
            className="btn-danger"
            onClick={() => onCancel(booking._id)}
          >
            Cancel Booking
          </button>
        )}
      </div>
    </div>
  );
};

export default BookingCard;
